            net = rounded(raw * (10000 - discount), data["rounding"])
            base = net if discounted_tax else raw
            tax = rounded(base * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            versions = sorted({row["version"] for row in packages[name]}, reverse=True)
            choices.append(versions + [-1])

        def valid(assignment):
            installed = {name: version for name, version in assignment.items() if version != -1}
            for name, bounds in roots.items():
                if name not in installed or not bounds[0] <= installed[name] <= bounds[1]:
                    return False
            for name, version in installed.items():
                if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                    return False

            graph = {name: [] for name in installed}
            for name, version in installed.items():
                row = next(row for row in packages[name] if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                        return False
                    graph[name].append(other)

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph[name])
            if reachable != set(installed):
                return False

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in graph)

        # Choices are ordered by the required descending-name version vector,
        # with absent (-1) after every installed version.
        def search(index, assignment):
            if index == len(names):
                return assignment.copy() if valid(assignment) else None
            name = names[index]
            for version in choices[index]:
                assignment[name] = version
                result = search(index + 1, assignment)
                if result is not None:
                    return result
            assignment.pop(name, None)
            return None

        result = search(0, {})
        if result is None:
            return {"error": "unsatisfiable"}
        return {"versions": {name: version for name, version in result.items() if version != -1}}
    return solve


def _build_component_07():
    from collections import Counter

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = Counter(job["group"] for job in selected)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(selected, key=lambda job: (job["start"], job["end"], job["id"]))
            active = []
            feasible = True
            for job in ordered:
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    feasible = False
                    break
            if not feasible:
                continue
            id_list = sorted(ids)
            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and id_list > best_ids)):
                best_value, best_ids = value, id_list
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if distances.get(state) != time:
                continue
            if time > data["deadline"]:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    new_mask = mask | bit.get(dest, 0)
                    next_state = (dest, new_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, new_mask, left))
        return {"arrival": None}
    return solve


